            st.push({cur, k});
            cur.clear();
            k = 0;
        } else if (c == ']') {
            auto [outer, times] = st.top(); st.pop();
            for (int t = 0; t < times; t++) outer += cur;
            cur = outer;
        } else {
            cur += c;
        }
    }
    return cur;
}

